import unittest

from views import header, inbox, settings_title


class TestViews(unittest.TestCase):
    def test_the_header(self):
        self.assertEqual(header(), 'Welcome back')

    def test_the_inbox(self):
        self.assertEqual(inbox(3), 'You have 3 new messages')

    def test_the_settings_title(self):
        self.assertEqual(settings_title(), 'Settings')

